void
PGSemaphoreLock(PGSemaphore sema)
{
	int			errStatus;

	/*
	 * Native signals cannot interrupt a threaded backend's semaphore wait:
	 * PostgreSQL signals are delivered through the role registry.  Bound the
	 * wait so crash-shutdown signals can be dispatched without relying on an
	 * unsafe process-wide signal handler.
	 */
	if (postgamma_in_backend_thread())
	{
		for (;;)
		{
			struct timespec deadline;

			postgamma_dispatch_pending_signals();
			if (clock_gettime(CLOCK_REALTIME, &deadline) != 0)
				elog(FATAL, "clock_gettime failed: %m");
			deadline.tv_nsec += 100000000L;
			if (deadline.tv_nsec >= 1000000000L)
			{
				deadline.tv_sec++;
				deadline.tv_nsec -= 1000000000L;
			}
			errStatus = sem_timedwait(PG_SEM_REF(sema), &deadline);
			if (errStatus == 0)
				return;
			if (errno != EINTR && errno != ETIMEDOUT)
				break;
		}
	}
	else
	{
		/* See notes in sysv_sema.c's implementation of PGSemaphoreLock. */
		do
		{
			errStatus = sem_wait(PG_SEM_REF(sema));
		} while (errStatus < 0 && errno == EINTR);
	}

	if (errStatus < 0)
		elog(FATAL, "semaphore wait failed: %m");
}

