# Keep a relation lock alive across the crash.  The monitor below will wait
# inside PGSemaphoreLock(), exercising crash-signal delivery to a blocked
# threaded backend rather than the latch-based pg_sleep() path.
$node->safe_psql(
	'postgres', q[
		CREATE TABLE postgamma_semaphore_blocker(id integer);
		BEGIN;
		LOCK TABLE postgamma_semaphore_blocker IN ACCESS EXCLUSIVE MODE;
		PREPARE TRANSACTION 'postgamma_semaphore_blocker';
	]);

test_adaptations.match:
# Start longrunning query in second session; its failure will signal that
# crash-restart has occurred.  The initial wait for the trivial select is to
# be sure that psql successfully connected to backend.
$monitor_stdin .= q[
SELECT $$psql-connected$$;
SELECT pg_sleep(3600);
];
ok( pump_until(
		$monitor, $psql_timeout, \$monitor_stdout, qr/psql-connected/m),
	'monitor connected');

test_adaptations.content:
# Block the second session behind the prepared transaction.  Its failure will
# signal that crash-restart has occurred.  Waiting until pg_stat_activity
# reports the relation-lock wait makes the semaphore path deterministic.
$monitor_stdin .= q[
SELECT $$psql-connected:$$ || pg_backend_pid();
SELECT count(*) FROM postgamma_semaphore_blocker;
];
ok( pump_until(
		$monitor, $psql_timeout, \$monitor_stdout, qr/psql-connected/m),
	'monitor connected');
my ($monitor_pid) = $monitor_stdout =~ /psql-connected:([[:digit:]]+)/;
ok(defined($monitor_pid), 'acquired monitor pid');
is( $node->poll_query_until(
		'postgres',
		"SELECT wait_event_type = 'Lock' AND wait_event = 'relation' "
		  . "FROM pg_stat_activity WHERE pid = $monitor_pid"),
	'1',
	'monitor is blocked in the relation-lock semaphore wait');

